#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll n, a, b;

ll chk(int x) {
    ll capacity = n;
    ll first = a, second = b;
    ll firstCount = 4, secondCount = 2;

    if (x == 1) {
        swap(first, second);
        swap(firstCount, secondCount);
    }

    const ll INF = (1LL << 60);

    if ((firstCount && first > capacity) ||
        (secondCount && second > capacity)) {
        return INF;
    }

    ll cnt = 1;
    ll remaining = capacity;
    vector<ll> leftovers;

    for (ll i = 0; i < firstCount; ++i) {
        if (remaining < first) {
            leftovers.push_back(remaining);
            remaining = capacity;
            ++cnt;
        }
        remaining -= first;
    }

    if (firstCount > 0)
        leftovers.push_back(remaining);

    size_t i = 0;
    remaining = capacity;
    bool usedNewBin = false;

    for (ll j = 0; j < secondCount; ++j) {
        while (i < leftovers.size() && leftovers[i] < second)
            ++i;

        if (i < leftovers.size()) {
            leftovers[i] -= second;
        } else {
            if (remaining < second) {
                remaining = capacity;
                ++cnt;
            }
            remaining -= second;
            usedNewBin = true;
        }
    }

    if (usedNewBin)
        ++cnt;

    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> a >> b;
    cout << min(chk(0), chk(1));

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int64 n, a, b;

int64 chk(bool reverse_order) {
    int64 first = a, second = b;
    int first_count = 4, second_count = 2;

    if (reverse_order) {
        swap(first, second);
        swap(first_count, second_count);
    }

    if (first > n || second > n)
        return LLONG_MAX / 4;

    vector<int64> remaining;
    int64 current = n;

    for (int i = 0; i < first_count; ++i) {
        if (current < first) {
            remaining.push_back(current);
            current = n;
        }
        current -= first;
    }
    remaining.push_back(current);

    size_t index = 0;
    int64 new_bins = 0;
    current = n;

    for (int i = 0; i < second_count; ++i) {
        while (index < remaining.size() && remaining[index] < second)
            ++index;

        if (index < remaining.size()) {
            remaining[index] -= second;
        } else {
            if (current < second) {
                ++new_bins;
                current = n;
            }
            if (current == n)
                ++new_bins;
            current -= second;
        }
    }

    return static_cast<int64>(remaining.size()) + new_bins;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> a >> b;

    int64 answer = min(chk(false), chk(true));
    cout << (answer >= LLONG_MAX / 4 ? -1 : answer);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, a, b;

int chk(int x) {
    int A = a, B = b;
    if (x == 1) swap(A, B);

    if (A > n || B > n) return INT_MAX / 2;

    int cnt = 1;
    int rem = n;
    vector<int> v;

    int firstCount = (x == 1 ? 2 : 4);
    for (int k = 0; k < firstCount; ++k) {
        if (rem >= A) {
            rem -= A;
        } else {
            v.push_back(rem);
            rem = n;
            ++cnt;
            --k;
        }
    }

    if (rem < n) v.push_back(rem);

    int secondCount = (x == 1 ? 4 : 2);
    int i = 0;
    bool usedNewBin = false;
    rem = n;

    for (int k = 0; k < secondCount;) {
        if (i < static_cast<int>(v.size()) && v[i] >= B) {
            v[i] -= B;
            ++k;
        } else if (i < static_cast<int>(v.size())) {
            ++i;
        } else if (rem >= B) {
            usedNewBin = true;
            rem -= B;
            ++k;
        } else {
            rem = n;
            ++cnt;
        }
    }

    if (usedNewBin) ++cnt;
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> a >> b;
    cout << min(chk(0), chk(1));
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, a, b;

int chk(bool reverseOrder) {
    vector<int> items;
    if (!reverseOrder) {
        items.insert(items.end(), 4, a);
        items.insert(items.end(), 2, b);
    } else {
        items.insert(items.end(), 2, b);
        items.insert(items.end(), 4, a);
    }

    vector<int> remaining;
    for (int item : items) {
        if (item > n) return INT_MAX / 2;

        bool placed = false;
        for (int &space : remaining) {
            if (space >= item) {
                space -= item;
                placed = true;
                break;
            }
        }

        if (!placed) {
            remaining.push_back(n - item);
        }
    }

    return static_cast<int>(remaining.size());
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> a >> b;
    cout << min(chk(false), chk(true));

    return 0;
}

